<section class="container page-section"><p class="breadcrumb"><a href="/">หน้าแรก</a> / ค้นหา</p><div class="page-heading"><p class="eyebrow">FIND YOUR STORY</p><h1>ค้นหาข้อมูล</h1><p>ค้นหาข่าว กิจกรรม และเอกสารประชาสัมพันธ์</p></div><form class="filters"><label class="search-field"><span class="sr-only">คำค้น</span><?= icon('search') ?><input name="q" value="<?= e($q) ?>" placeholder="คุณกำลังมองหาอะไร?" maxlength="200" required></label><input type="hidden" name="type" value="<?= e($type) ?>"><button class="button">ค้นหา</button></form><nav class="tabs"><?php foreach([''=>'ทั้งหมด','post'=>'ข่าว','event'=>'กิจกรรม','document'=>'เอกสาร'] as $key=>$label): ?><a class="<?= $type===$key?'selected':'' ?>" href="/search?<?= e(http_build_query(['q'=>$q,'type'=>$key])) ?>"><?= $label ?></a><?php endforeach ?></nav><?php if($q===''): $emptyTitle='เริ่มค้นหาข้อมูล'; $emptyText='พิมพ์คำสำคัญเพื่อค้นหาข่าว กิจกรรม หรือเอกสาร'; require ROOT . '/views/partials/empty.php'; elseif(!$items): $emptyTitle='ไม่พบข้อมูลที่ตรงกับคำค้น'; $emptyText='ลองเปลี่ยนคำค้น หรือเลือกประเภททั้งหมด'; require ROOT . '/views/partials/empty.php'; else: ?><p class="result-count">พบ <?= $count ?> รายการ สำหรับ “<?= e($q) ?>”</p><div class="search-results"><?php foreach($items as $row): $link=$row['type']==='document'?'/media?tab=document&q='.rawurlencode($row['title']):public_link($row); ?><a class="search-result" href="<?= e($link) ?>"><img src="<?= e(image_url($row['cover_id']?(int)$row['cover_id']:null)) ?>" alt="" loading="lazy"><div><span class="badge"><?= e(CONTENT_TYPES[$row['type']]) ?></span><h2><?= e($row['title']) ?></h2><p><?= e($row['excerpt']) ?></p><small><?= e(thai_date($row['published_at'])) ?></small></div><?= icon('arrow') ?></a><?php endforeach ?></div><?php pagination($count,$page); endif ?></section>
